import re

ESC = {'s': ' ', 'p': '|', '/': '/', '\\': '\\', 'n': '\n', 't': '\t'}

def unesc(v):
    return re.sub(r'\\(.)', lambda m: ESC.get(m.group(1), m.group(1)), v)

def pairs(s):
    d = {}
    for tok in s.split():
        if '=' in tok:
            k, v = tok.split('=', 1)
            d[k] = unesc(v)
        else:
            d[tok] = ''
    return d

def parse(lines):
    rows, rl, kv, kl, skip = [], [], {}, [], []
    for i, ln in enumerate(lines):
        s = ln.strip()
        if not s:
            continue
        m = re.match(r'error\s+(.*)$', s)
        if m:
            kv.update(pairs(m.group(1)))
            kl.append(i)
            continue
        if '=' in s:
            for rec in s.split('|'):
                if rec.strip():
                    rows.append(pairs(rec))
            rl.append(i)
            continue
        skip.append(i)
    keys = []
    for r in rows:
        for k in r:
            if k not in keys:
                keys.append(k)
    recs = [dict((k, r.get(k, '')) for k in keys) for r in rows]
    blocks = []
    if rl:
        blocks.append({'name': 'clients', 'kind': 'table', 'lines': rl, 'records': recs})
    if kl:
        blocks.append({'name': 'status', 'kind': 'kv', 'lines': kl, 'records': [kv]})
    return {'blocks': blocks, 'skip': skip}
